  background: #1e1e1e;
  border-radius: 12px;
  box-shadow: none;
  padding: 8px;               /* 缩小整体容器内边距 */
  position: relative;
}
.header {
  text-align: center;
  color: #bb86fc;
  font-weight: 500;
  font-size: 16px;
  margin-bottom: 6px;         /* 缩小标题与按钮间距 */
  letter-spacing: 1px;
}
.option {
  background: rgba(255,255,255,0.05);
