        border-color: var(--accent-color);
        color: var(--bg-color);
        font-weight: 700;
        box-shadow: 0 0 8px rgba(42, 110, 246, 0.12);
      }
      .feature-option.disabled {
        cursor: not-allowed;
        opacity: 0.75;
      }

      /* 第六步：人物竖排 */
      #actor-container {
        display: flex;
        flex-direction: column;
        gap: 0.6rem;
        max-height: none; /* 不要滚动条，直接全部竖排显示 */
        padding-top: 0.25rem;
      }
      .actor-option {
        background-color: rgba(6, 10, 14, 0.45);
        border: 1px solid var(--border-color);
        color: var(--text-secondary-color);
        padding: 0.65rem 0.9rem;
        border-radius: 6px;
        cursor: pointer;
        transition: all 0.12s ease;
        font-size: 0.95rem;
        text-align: left;
      }
      .actor-option:hover { border-color: var(--accent-hover); color: var(--text-color); transform: translateY(-3px); }
      .actor-option.selected {
        background-color: var(--accent-color);
        border-color: var(--accent-hover);
        color: var(--bg-color);
        font-weight: 700;
        box-shadow: 0 0 10px rgba(42,110,246,0.12);
      }
      .actor-option small { display:block; color:var(--text-secondary-color); margin-top:0.35rem; font-size:0.86rem; }

      .custom-input-container { margin-top: 1.8rem; display:flex; flex-direction: column; gap:0.6rem; }
      .custom-input-container label {
        font-family: var(--font-display);
        color: var(--text-secondary-color);
        font-size: 1.2rem;
        letter-spacing: 1px;
      }
      .custom-input, .custom-textarea {
        width: 100%;
        background-color: rgba(6, 10, 14, 0.45);
        border: 1px solid var(--border-color);
        border-radius: 4px;
        padding: 0.75rem 1rem;
        color: var(--text-color);
        font-family: var(--font-main);
        font-size: 1rem;
        box-sizing: border-box;
        transition: border-color 0.12s ease;
      }
      .custom-input:focus, .custom-textarea:focus {
        outline: none;
        border-color: var(--accent-color);
        box-shadow: 0 0 10px rgba(42, 110, 246, 0.08);
      }
      .custom-textarea { min-height: 90px; resize: vertical; }

      @media (max-width: 768px) {
        body { padding: 0.6rem; }
        .generator-container { padding: 1.2rem 1rem; border-radius: 4px; }
        .corner { width: 14px; height: 14px; border-width: 1px; }
        .corner-tl { top: 8px; left: 8px; }
        .corner-tr { top: 8px; right: 8px; }
        .corner-bl { bottom: 8px; left: 8px; }
        .corner-br { bottom: 8px; right: 8px; }
        .screen-header { margin-bottom: 1rem; padding-bottom: 0.8rem; }
        .screen-header h2 { font-size: 2.2rem; letter-spacing: 2px; }
        .screen-header p { font-size: 0.9rem; }
        .randomize-btn { top: 1rem; right: 0; transform: none; }
        .randomize-btn i { font-size: 22px; }
        .selection-grid { grid-template-columns: 1fr; gap: 0.9rem; }
        .card { padding: 1rem; }
        .card h3 { font-size: 1.1rem; }
        .card p { font-size: 0.85rem; }
        .nav-buttons { flex-direction: column; gap: 0.8rem; margin-top: 1.6rem; }
        .nav-buttons span { display: none; }
        .btn { padding: 0.55rem 1rem; font-size: 1rem; letter-spacing: 1px; }
        .summary-item { padding: 0.6rem 0.8rem; font-size: 0.95rem; }
        .summary-label { min-width: 80px; }
        .summary-value { text-align: left; flex-grow:1; word-break: break-word; }
        .feature-category h4 { font-size: 1.2rem; padding-bottom: 0.3rem; }
        .feature-options-grid { gap: 0.45rem; }
        .feature-option { padding: 0.35rem 0.75rem; font-size: 0.86rem; }
        #actor-container { max-height: none; padding-top: 0.2rem; }
        .actor-option { padding: 0.45rem 0.6rem; font-size: 0.86rem; }
        .custom-input-container { margin-top: 1.2rem; }
        .custom-input-container label { font-size: 1rem; }
        .custom-input, .custom-textarea { padding: 0.55rem 0.7rem; font-size: 0.92rem; }
        .custom-textarea { min-height: 64px; }
      }
    </style>
  </head>
  <body>
    <div class="generator-container">
      <span class="corner corner-tl"></span>
      <span class="corner corner-tr"></span>
      <span class="corner corner-bl"></span>
      <span class="corner corner-br"></span>

      <div id="screen-gender" class="screen active">
        <div class="screen-header">
          <div class="randomize-btn" title="随机选择" data-screen-id="screen-gender">
            <i class="fa-solid fa-dice-six"></i>
          </div>
          <h2>第一步：确定性别</h2>
          <p>请选择人物的性别</p>
        </div>
        <div class="selection-grid">
          <div class="card" data-type="gender" data-value="男">
            <h3>男性</h3>
            <p>我猜你是来当主人的。</p>
          </div>
          <div class="card" data-type="gender" data-value="女">
            <h3>女性</h3>
            <p>既可以当主人，也可以当奴隶。</p>
          </div>
        </div>
        <div class="nav-buttons">
          <span></span><button id="to-status" class="btn btn-primary" disabled>下一步</button>
        </div>
      </div>

      <div id="screen-status" class="screen">
        <div class="screen-header">
          <div class="randomize-btn" title="随机选择" data-screen-id="screen-status">
            <i class="fa-solid fa-dice-six"></i>
          </div>
          <h2>第二步：社会身份划分</h2>
          <p>男女各不相同</p>
        </div>
        <div id="status-options"></div>
        <div class="nav-buttons">
          <button class="btn back-btn" data-target="screen-gender">上一步</button>
          <button id="to-profession-or-category" class="btn btn-primary" disabled>下一步</button>
        </div>
      </div>

      <div id="screen-profession-category" class="screen">
        <div class="screen-header">
          <div class="randomize-btn" title="随机选择" data-screen-id="screen-profession-category">
            <i class="fa-solid fa-dice-six"></i>
          </div>
          <h2>第三步：选择职业大类</h2>
          <p>来吧，选择行业或类别</p>
        </div>
        <div id="profession-category-options" class="selection-grid"></div>
        <div class="nav-buttons">
          <button class="btn back-btn" data-target="screen-status">上一步</button>
          <button id="to-profession" class="btn btn-primary" disabled>下一步</button>
        </div>
      </div>

      <div id="screen-profession" class="screen">
        <div class="screen-header">
          <div class="randomize-btn" title="随机选择" data-screen-id="screen-profession">
            <i class="fa-solid fa-dice-six"></i>
          </div>
          <h2>第四步：具体单位或职业</h2>
          <p>具体是干嘛的？</p>
        </div>
        <div id="profession-options" class="selection-grid"></div>
        <div class="custom-input-container">
          <label for="custom-profession-input">或自定义职业:</label>
          <input
            type="text"
            id="custom-profession-input"
            class="custom-input"
            placeholder="在此输入自定义职业名称..."
          />
        </div>
        <div class="nav-buttons">
          <button class="btn back-btn" data-target="screen-profession-category">上一步</button>
          <button id="to-features" class="btn btn-primary" disabled>下一步</button>
        </div>
      </div>

      <div id="screen-features" class="screen">
        <div class="screen-header">
          <div class="randomize-btn" title="随机选择" data-screen-id="screen-features">
            <i class="fa-solid fa-dice-six"></i>
          </div>
          <h2>第五步：身体属性</h2>
          <p>你的身体，是什么情况？</p>
        </div>
        <div id="features-container"></div>
        <div class="custom-input-container">
          <label for="custom-features-input">补充身体特征 (可选):</label>
          <input
            type="text"
            id="custom-features-input"
            class="custom-input"
            placeholder="例如：纹身、戴眼镜、伤疤..."
          />
        </div>
        <div class="nav-buttons">
          <button class="btn back-btn" data-target="screen-profession">上一步</button>
          <button id="to-actor" class="btn btn-primary" disabled>下一步</button>
        </div>
      </div>

      <!-- 第六步：人物选择 -->
      <div id="screen-actor" class="screen">
        <div class="screen-header">
          <div class="randomize-btn" title="随机选择" data-screen-id="screen-actor">
            <i class="fa-solid fa-dice-six"></i>
          </div>
          <h2>第六步：初始关系 (可选)</h2>
          <p>可跳过（不选），可多选（最多三人）</p>
        </div>

        <div id="actor-container"></div>

        <div class="custom-input-container">
          <label for="custom-actor-input">补充人员名字（可选）:</label>
          <input
            type="text"
            id="custom-actor-input"
            class="custom-input"
            placeholder="例如：自定义人物名，多个用逗号分隔..."
          />
        </div>

        <div class="custom-input-container">
          <label for="relation-input">你和她的关系——你是她的什么？（可选，留空时默认“朋友”）:</label>
          <input
            type="text"
            id="relation-input"
            class="custom-input"
            placeholder="例如：家人、主人、同事、恋人..."
          />
        </div>

        <div class="nav-buttons">
          <button class="btn back-btn" data-target="screen-features">上一步</button>
          <button id="to-summary" class="btn btn-primary">下一步</button>
        </div>
      </div>

      <div id="screen-summary" class="screen">
        <div class="screen-header">
          <h2>最终档案确认</h2>
          <p>确认下列信息，点击"注入世界"后即可生成开局</p>
        </div>
        <div id="summary-content"></div>
        <div class="custom-input-container summary-custom-scene">
          <label for="custom-scene-input">开场背景和场景自定义:</label>
          <textarea
            id="custom-scene-input"
            class="custom-textarea"
            placeholder="在此输入你希望的开场背景，例如"在生日这天，我的高中老师苏晴突然上门找我…" 留空则由AI补充。"
          ></textarea>
        </div>
        <div class="nav-buttons">
          <button class="btn back-btn" data-target="screen-actor">上一步</button>
          <button id="confirm-and-start" class="btn btn-primary">注入世界</button>
        </div>
      </div>
    </div>

    <script>
      // === 完整数据 ===
      const data = {
        gender: {
          男: {
            status: {
              '公司老板/店长': {
                professionCategories: {
                  食宿: { professions: ['玉味私房菜馆', '灯塔餐厅', '雀语咖啡馆', '洁序汤泉', '常安旅舍', '怡心足浴'] },
                  艺术: { professions: ['面影馆', '影绣室(摄影工作室)'] },
                  色情: { professions: ['爱语成人用品店', '欲望造梦馆', '宠物小站'] },
                  其他: { professions: ['柔感制服定制屋', '伴途咨询', '核心点健身房', '好用二手店'] },
                },
              },
              '普通员工': {
                professionCategories: {
                  服务类: { professions: ['玉味私房菜馆', '灯塔餐厅', '雀语咖啡馆', '好用二手店', '核心点健身房当教练', '伴途咨询', '洁序汤泉', '常安旅舍', '怡心足浴'] },
                  技术类: { professions: ['影绣室(摄影工作室)', '柔感制服定制屋','芮馨家政当接待员', '星光学院当教师'] },
                },
              },
              '向阳中学师生员工': {
                professionCategories: {
                  学生: { professions: ['初中部, 是学生', '高中部, 是学生'] },
                  教师: { professions: ['初中部当教师', '高中部当教师', '当教导主任', '当班主任'] },
                },
              },
              '应届毕业生': {
                professionCategories: {
                  实习类: { professions: ['影绣室(摄影工作室)', '伴途咨询','柔感制服定制屋'] },
                  待业类: { professions: ['家里，还未找到工作', '家里，没去找工作', '打零工维持生活，还未找到正式工作'] },
                },
              },
            },
            features: {
              智力: ['天才', '聪慧', '平庸', '迟钝'],
              外貌: ['俊美无俦', '相貌英俊', '面容普通', '有些丑陋'],
              身材: ['身材健壮', '标准体型', '较为瘦弱', '肥胖油腻'],
            },
          },

          女: {
            status: {
              '公民': {
                professionCategories: {
                  '公司老板/店长': { professions: ['玉味私房菜馆', '灯塔餐厅', '雀语咖啡馆', '面影馆', '影绣室(摄影工作室)', '柔感制服定制屋', '伴途咨询', '好用二手店', '核心点健身房', '洁序汤泉', '常安旅舍', '欲望造梦馆', '怡心足浴']},
                  '普通员工': { professions: ['玉味私房菜馆', '灯塔餐厅', '雀语咖啡馆', '好用二手店', '伴途咨询', '影绣室(摄影工作室)', '柔感制服定制屋','芮馨家政', '星光学院当教师', '核心点健身房当教练', '洁序汤泉', '常安旅舍', '怡心足浴'] },
                  '向阳中学学生': { professions: ['初中部, 是学生', '高中部, 是学生'] },
                  '向阳中学教师': { professions: ['初中部当教师', '高中部当教师', '当教导主任', '当班主任'] },
                  '应届毕业生': { professions: ['家里，还未找到工作', '家里，没去找工作'] },
                },
              },
              '奴隶': {
                professionCategories: {
                  '普通奴隶': { professions: ['面影馆', '7-11便利店', '爱语', '芮馨家政', '小杯出行', '星光学院当学生', '欲望造梦馆', '向阳中学初中部, 是学生', '向阳中学高中部, 是学生学生', '向阳中学当教师'] },
                  '家畜级奴隶': { professions: ['宠物小站作为待售宠物'] },
                },
              },
            },
            features: {
              外貌: ['绝美', '清秀', '普通', '平凡'],
              气质: ['温柔', '干练', '可爱', '恬静', '坚强'],
              身材: ['匀称', '苗条', '高挑', '娇小', '丰满'],
            },
          },
        },
      };

      // -- selections and order --
      const selections = {};
      const selectionOrder = [
        'gender',
        'status',
        'professionCategory',
        'profession',
        'feature',
        'actor', // 第六步：人物选择（多选）
        'customActor',
        'relation',
        'customScene',
      ];

      function getRandomElement(arr) { return arr[Math.floor(Math.random() * arr.length)]; }
      function navigateTo(screenId) {
        document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
        const el = document.getElementById(screenId);
        if (el) el.classList.add('active');
      }

      function renderCardOptions(containerId, options, type) {
        const container = document.getElementById(containerId);
        container.innerHTML = '';
        const grid = document.createElement('div');
        grid.className = 'selection-grid';

        // options can be array OR object mapping names -> data
        if (Array.isArray(options)) {
          options.forEach(opt => grid.appendChild(createCard(type, opt, '')));
        } else {
          for (const [key, value] of Object.entries(options)) {
            let desc = '';
            // if nested structure, try to extract a friendly description
            if (value && typeof value === 'object') {
              if (value.professions) desc = `示例职位：${value.professions.slice(0,2).join('、')}`;
              else if (value.professionsByCategory) desc = '';
              else if (value.professionCategories) desc = '';
              else if (value.description) desc = value.description;
            }
            grid.appendChild(createCard(type, key, desc));
          }
        }
        container.appendChild(grid);

        // enable/disable next button in this screen based on selection state
        const nextButton = container.closest('.screen')?.querySelector('.btn-primary');
        if (nextButton) {
          if (type === 'profession' && document.getElementById('custom-profession-input').value.trim()) {
            nextButton.disabled = false;
          } else {
            nextButton.disabled = !selections[type];
          }
        }
      }

      function createCard(type, value, description) {
        const el = document.createElement('div');
        el.className = 'card';
        el.dataset.type = type;
        el.dataset.value = value;
        if (selections[type] === value) el.classList.add('selected');
        const title = document.createElement('h3');
        title.textContent = value;
        el.appendChild(title);
        if (description) {
          const p = document.createElement('p');
          p.textContent = description;
          el.appendChild(p);
        }
        return el;
      }

      // features renderer (unchanged logic)
      function renderFeaturesScreen() {
        const container = document.getElementById('features-container');
        container.innerHTML = '';
        selections.feature = selections.feature || {};
        const featureSet = data.gender[selections.gender].features;
        for (const category in featureSet) {
          const categoryDiv = document.createElement('div');
          categoryDiv.className = 'feature-category';
          const title = document.createElement('h4');
          title.textContent = category;
          categoryDiv.appendChild(title);
          const optionsGrid = document.createElement('div');
          optionsGrid.className = 'feature-options-grid';
          const levels = featureSet[category];
          levels.forEach(level => {
            const optionDiv = document.createElement('div');
            optionDiv.className = 'feature-option';
            optionDiv.dataset.category = category;
            optionDiv.dataset.value = level;
            optionDiv.textContent = level;
            optionsGrid.appendChild(optionDiv);
          });
          categoryDiv.appendChild(optionsGrid);
          container.appendChild(categoryDiv);

          // restore previous selection if exists
          if (selections.feature[category]) {
            const sel = optionsGrid.querySelector(`[data-value="${selections.feature[category]}"]`);
            if (sel) sel.classList.add('selected');
          }
        }
        checkAllFeaturesSelected();
      }

      function checkAllFeaturesSelected() {
        const featureSet = data.gender[selections.gender]?.features || {};
        const allSelected = Object.keys(featureSet).every(cat => selections.feature && selections.feature[cat]);
        document.getElementById('to-actor').disabled = !allSelected;
      }

      // 人物名单（含设定简介）
      const actorList = [
        { name: '林昕', desc: '{{user}}的邻居，出身豪门的贵妇人。' },
        { name: '刘妍', desc: '{{user}}的网友与邻居，随和风趣，邻家大姐姐，芮馨家政G4注册员工。' },
        { name: '白荷', desc: '丰满，{{user}}的老朋友。' },
        { name: '萌萌', desc: '奴隶，王哥的宠物。' },
        { name: '邹怡雯', desc: '辣妹，芮馨家政G3注册员工。' },
        { name: '苏晴', desc: '{{user}}的高中老师，也是{{user}}的奴隶。' },
        { name: '武妤', desc: '爱语成人用品店看板娘。' },
        { name: '苏瑶', desc: '萝莉妈妈，芮馨家政G1注册员工。' },
        { name: '季穆仪', desc: '乐天派，喜欢尝试新事物，芮馨家政G2注册员工。' },
        { name: '武钰', desc: '单身母亲，金牌长期住家保姆，芮馨家政G2注册员工。' },
        { name: '晓娟', desc: '萝莉，前柔术演员，好色，芮馨家政G3注册员工。' },
        { name: '周煜文', desc: '{{user}}的青梅竹马。' },
        { name: '萧燃', desc: '健身教练，假小子。' },
        { name: '芳岚', desc: '英姿飒爽，莺姬服务公司性服务员。' },
        { name: '沈若柠', desc: '女强人，有孩子的母亲，莺姬服务公司高级管理人员。' }
      ];

      function renderActorScreen() {
        const container = document.getElementById('actor-container');
        container.innerHTML = '';
        selections.actor = Array.isArray(selections.actor) ? selections.actor : [];

        actorList.forEach(actor => {
          const opt = document.createElement('div');
          opt.className = 'actor-option';
          opt.dataset.value = actor.name;
          opt.innerHTML = `<strong>${actor.name}</strong><small>${actor.desc}</small>`;

          if (selections.actor.includes(actor.name)) opt.classList.add('selected');

          opt.addEventListener('click', () => {
            selections.actor = Array.isArray(selections.actor) ? selections.actor : [];
            const idx = selections.actor.indexOf(actor.name);
            if (idx > -1) {
              selections.actor.splice(idx, 1);
              opt.classList.remove('selected');
            } else {
              selections.actor.push(actor.name);
              opt.classList.add('selected');
            }
          });

          container.appendChild(opt);
        });

        // actor optional -> to-summary always enabled
        document.getElementById('to-summary').disabled = false;
      }

      function handleRandomize(screenId) {
        const screenElement = document.getElementById(screenId);
        if (!screenElement) return;
        switch (screenId) {
          case 'screen-gender':
          case 'screen-status':
          case 'screen-profession-category':
            const cards = screenElement.querySelectorAll('.card:not(.disabled)');
            if (cards.length > 0) getRandomElement(Array.from(cards)).click();
            break;
          case 'screen-profession':
            document.getElementById('custom-profession-input').value = '';
            delete selections.profession;
            const profCards = screenElement.querySelectorAll('.card:not(.disabled)');
            if (profCards.length > 0) getRandomElement(Array.from(profCards)).click();
            break;
          case 'screen-features':
            document.getElementById('custom-features-input').value = '';
            delete selections.customFeature;
            screenElement.querySelectorAll('.feature-category').forEach(cat => {
              const opts = cat.querySelectorAll('.feature-option:not(.disabled)');
              if (opts.length > 0) getRandomElement(Array.from(opts)).click();
            });
            break;
          case 'screen-actor':
            document.getElementById('custom-actor-input').value = '';
            document.getElementById('relation-input').value = '';
            delete selections.customActor;
            delete selections.relation;
            selections.actor = [];
            const optActors = Array.from(screenElement.querySelectorAll('.actor-option:not(.disabled)'));
            optActors.forEach(m => m.classList.remove('selected'));
            if (optActors.length > 0) {
              const num = Math.floor(Math.random() * Math.min(4, optActors.length + 1));
              const shuffled = optActors.sort(() => 0.5 - Math.random());
              for (let i = 0; i < num; i++) shuffled[i].click();
            }
            break;
        }
      }

      function updateSelection(type, value) {
        if (selections[type] === value) return;
        selections[type] = value;
        const currentIndex = selectionOrder.indexOf(type);
        for (let i = currentIndex + 1; i < selectionOrder.length; i++) {
          const key = selectionOrder[i];
          delete selections[key];
          const el = document.getElementById(`custom-${key}-input`);
          if (el) el.value = '';
        }
      }

      // Delegated click handling
      document.body.addEventListener('click', function (e) {
        const card = e.target.closest('.card');
        const featureOption = e.target.closest('.feature-option');
        const backBtn = e.target.closest('.back-btn');
        const randomizeBtn = e.target.closest('.randomize-btn');
        const nextBtn = e.target.closest('.btn-primary');

        if (randomizeBtn) {
          handleRandomize(randomizeBtn.dataset.screenId);
          return;
        }

        if (card) {
          // special handling: when click a professionCategory for female '公民' identity that uses professionsByCategory,
          // we must drill down differently
          const type = card.dataset.type;
          const value = card.dataset.value;

          updateSelection(type, value);

          // visually mark selected
          const container = card.parentElement;
          if (container) container.querySelectorAll('.card').forEach(c => c.classList.remove('selected'));
          card.classList.add('selected');

          // enable next button in this screen
          const btn = card.closest('.screen').querySelector('.btn-primary');
          if (btn) btn.disabled = false;
        }

        if (featureOption && !featureOption.classList.contains('disabled')) {
          selections.feature = selections.feature || {};
          selections.feature[featureOption.dataset.category] = featureOption.dataset.value;
          featureOption.parentElement.querySelectorAll('.feature-option').forEach(opt => opt.classList.remove('selected'));
          featureOption.classList.add('selected');
          checkAllFeaturesSelected();
        }

        if (backBtn) {
          navigateTo(backBtn.dataset.target);
        }
        if (nextBtn && !nextBtn.disabled) {
          handleNext(nextBtn.id);
        }
      });

      // input handlers
      document.getElementById('custom-profession-input')?.addEventListener('input', e => {
        const value = e.target.value.trim();
        if (value) {
          updateSelection('profession', value);
          document.querySelectorAll('#profession-options .card').forEach(c => c.classList.remove('selected'));
          document.getElementById('to-features').disabled = false;
        } else {
          delete selections.profession;
          document.getElementById('to-features').disabled = true;
        }
      });

      document.getElementById('custom-features-input').addEventListener('input', e => {
        selections.customFeature = e.target.value.trim();
      });
      document.getElementById('custom-actor-input').addEventListener('input', e => {
        selections.customActor = e.target.value.trim();
      });
      document.getElementById('relation-input').addEventListener('input', e => {
        selections.relation = e.target.value.trim();
      });
      document.getElementById('custom-scene-input').addEventListener('input', e => {
        selections.customScene = e.target.value.trim();
      });

      // Main next-step handler
      function handleNext(nextBtnId) {
        switch (nextBtnId) {
          case 'to-status':
            renderCardOptions('status-options', data.gender[selections.gender].status, 'status');
            navigateTo('screen-status');
            break;

          case 'to-profession-or-category':
            const statusInfo = data.gender[selections.gender].status[selections.status];
            // For female, there are two main identities: '公民' and '奴隶'
            if (selections.gender === '女') {
              if (selections.status === '公民') {
                // render second-level identities (公司老板/普通员工/应届毕业生)
                renderCardOptions('profession-category-options', data.gender.女.status.公民.professionCategories, 'professionCategory');
                navigateTo('screen-profession-category');
              } else if (selections.status === '奴隶') {
                // for 奴隶 render '普通奴隶' and '家畜级奴隶'
                renderCardOptions('profession-category-options', data.gender.女.status.奴隶.professionCategories, 'professionCategory');
                navigateTo('screen-profession-category');
              } else {
                // fallback
                renderCardOptions('profession-category-options', statusInfo.professionCategories || {}, 'professionCategory');
                navigateTo('screen-profession-category');
              }
              break;
            }

            // For male or other: if professionCategories present -> show third step categories, else go to profession
            if (statusInfo && statusInfo.professionCategories) {
              renderCardOptions('profession-category-options', statusInfo.professionCategories, 'professionCategory');
              navigateTo('screen-profession-category');
            } else if (statusInfo && statusInfo.professions) {
              renderCardOptions('profession-options', statusInfo.professions, 'profession');
              navigateTo('screen-profession');
            } else {
              // fallback: show empty profession options
              renderCardOptions('profession-options', [], 'profession');
              navigateTo('screen-profession');
            }
            break;

          case 'to-profession':
            // This handles when a user picked a professionCategory -> we must decide what to render next.
            // For male side: professionCategory key maps directly to an object with `professions` array.
            // For female '公民' side: professionCategory keys (e.g. '公司老板') contain an inner mapping 'professionsByCategory' or similar.
            const genderKey = selections.gender;
            const cat = selections.professionCategory;
            if (!cat) {
              renderCardOptions('profession-options', [], 'profession');
              navigateTo('screen-profession');
              return;
            }

            // MALE typical path
            if (genderKey === '男') {
              const maleStatusObj = data.gender.男.status[selections.status];
              const catObj = maleStatusObj && maleStatusObj.professionCategories && maleStatusObj.professionCategories[cat];
              if (catObj && catObj.professions) {
                renderCardOptions('profession-options', catObj.professions, 'profession');
              } else {
                // fallback empty
                renderCardOptions('profession-options', [], 'profession');
              }
              navigateTo('screen-profession');
              break;
            }

            // FEMALE path
            if (genderKey === '女') {
              // If user selected from top-level '公民' -> professionCategory is one of '公司老板'/'普通员工'/'应届毕业生'
              // Need to show next-level categories (e.g. 餐饮/艺术/设计) if present.
              const femaleStatus = data.gender.女.status[selections.status];
              if (selections.status === '公民' && femaleStatus && femaleStatus.professionCategories) {
                const identityObj = femaleStatus.professionCategories[selections.professionCategory];
                // identityObj may have professionsByCategory OR professions directly
                if (identityObj && identityObj.professionsByCategory) {
                  // show the industry categories (e.g., 餐饮/艺术/设计)
                  renderCardOptions('profession-options', Object.keys(identityObj.professionsByCategory), 'profession');
                } else if (identityObj && identityObj.professions) {
                  renderCardOptions('profession-options', identityObj.professions, 'profession');
                } else {
                  renderCardOptions('profession-options', [], 'profession');
                }
                navigateTo('screen-profession');
                break;
              }

              // If user selected '奴隶' -> professionCategory is one of '普通奴隶'/'家畜级奴隶'
              if (selections.status === '奴隶' && femaleStatus && femaleStatus.professionCategories) {
                const slaveTypeObj = femaleStatus.professionCategories[selections.professionCategory];
                // slaveTypeObj should have professionsByCategory
                if (slaveTypeObj && slaveTypeObj.professionsByCategory) {
                  renderCardOptions('profession-options', Object.keys(slaveTypeObj.professionsByCategory), 'profession');
                } else if (slaveTypeObj && slaveTypeObj.professions) {
                  renderCardOptions('profession-options', slaveTypeObj.professions, 'profession');
                } else {
                  renderCardOptions('profession-options', [], 'profession');
                }
                navigateTo('screen-profession');
                break;
              }

              // fallback
              renderCardOptions('profession-options', [], 'profession');
              navigateTo('screen-profession');
              break;
            }

            // default fallback
            renderCardOptions('profession-options', [], 'profession');
            navigateTo('screen-profession');
            break;

          case 'to-features':
            renderFeaturesScreen();
            navigateTo('screen-features');
            break;

          case 'to-actor':
            renderActorScreen();
            navigateTo('screen-actor');
            break;

          case 'to-summary':
            buildSummary();
            navigateTo('screen-summary');
            break;

          case 'confirm-and-start':
            let finalString = `{{user}}本人信息：性别：${selections.gender}，身份为${selections.status}，`;
            if (selections.professionCategory) finalString += `职业大类为${selections.professionCategory}，`;
            if (selections.profession) finalString += `具体工作在${selections.profession}。`;
            if (selections.feature) {
              const fdesc = Object.entries(selections.feature).map(([k,v]) => `${k}：${v}`).join('，');
              finalString += ` 身体属性为 ${fdesc}。`;
            }
            if (selections.customFeature) finalString += ` 补充特征：${selections.customFeature}。`;

            // actors: selected + custom
            let actors = [];
            if (Array.isArray(selections.actor) && selections.actor.length>0) actors = actors.concat(selections.actor);
            if (selections.customActor) {
              const parsed = selections.customActor.split(/[,，;；\n]/).map(s=>s.trim()).filter(Boolean);
              actors = actors.concat(parsed);
            }
            const relation = selections.relation && selections.relation.trim() ? selections.relation.trim() : null;
            if (actors.length>0) {
              finalString += ` 角色关系: 成为了${actors.join('、')}的${relation ? relation : '朋友'}。`;
            }

            if (selections.customScene) finalString += ` 自定义开场：${selections.customScene}；`;
            finalString += ' 请根据世界观，生成符合人物身份与设定的开局。';

              console.log(finalString);

  // --- 发送锁（防止重复触发多次发送） ---
  if (!window.__sending_profile) window.__sending_profile = false;

  if (window.__sending_profile) {
    // 如果已经在发送中，直接返回（避免重复）
    return;
  }
  window.__sending_profile = true;

  try {
    if (typeof triggerSlash === 'function') {
      try {
        // 真正发送（仅会执行一次，因有锁保护）
        triggerSlash(`/send ${finalString}|/trigger`);
      } catch (err) {
        // triggerSlash 内部出错也捕获，避免程序中断
        console.error('triggerSlash 调用失败：', err);
      }
    }

    // 显示你原先的“已注入”界面
    const finalDiv = document.createElement('div');
    finalDiv.style.padding = '20px';
    finalDiv.style.textAlign = 'center';
    const finalTitle = document.createElement('h2');
    finalTitle.className = 'screen-header';
    finalTitle.style.cssText = 'margin-bottom:1rem;border:none;';
    finalTitle.textContent = '档案已发送';
    const finalText = document.createElement('p');
    finalText.style.color = 'var(--accent-color)';
    finalText.style.fontSize = '1.05rem';
    finalText.textContent = '[档案已生成并注入聊天栏...]';
    finalDiv.appendChild(finalTitle);
    finalDiv.appendChild(finalText);
    document.querySelector('.generator-container').innerHTML = '';
    document.querySelector('.generator-container').appendChild(finalDiv);

  } finally {
    // 0.5s 后解除锁（避免短时间双触发），如果你希望更长可调大延迟
    setTimeout(() => { window.__sending_profile = false; }, 500);
  }
  break;
        }
      }

      function buildSummary() {
        const summaryContainer = document.getElementById('summary-content');
        summaryContainer.innerHTML = '';
        summaryContainer.className = 'summary-section';
        const fields = {
          性别: 'gender',
          社会身份: 'status',
          职业大类: 'professionCategory',
          具体职业: 'profession',
        };
        for (const [label, key] of Object.entries(fields)) {
          if (selections[key]) {
            const item = document.createElement('div');
            item.className = 'summary-item';
            item.innerHTML = `<span class="summary-label">${label}</span><span class="summary-value">${selections[key]}</span>`;
            summaryContainer.appendChild(item);
          }
        }
        if (selections.feature) {
          for (const [cat, lvl] of Object.entries(selections.feature)) {
            const item = document.createElement('div');
            item.className = 'summary-item';
            item.innerHTML = `<span class="summary-label">${cat}</span><span class="summary-value">${lvl}</span>`;
            summaryContainer.appendChild(item);
          }
        }
        if (selections.customFeature) {
          const item = document.createElement('div');
          item.className = 'summary-item';
          item.innerHTML = `<span class="summary-label">补充特征</span><span class="summary-value">${selections.customFeature}</span>`;
          summaryContainer.appendChild(item);
        }

        // 人物展示（多选 + 自定义）
        let actors = [];
        if (Array.isArray(selections.actor) && selections.actor.length > 0) actors = actors.concat(selections.actor);
        if (selections.customActor) {
          const parsed = selections.customActor.split(/[,，;；\n]/).map(s=>s.trim()).filter(Boolean);
          actors = actors.concat(parsed);
        }
        if (actors.length > 0) {
          const item = document.createElement('div');
          item.className = 'summary-item';
          const rel = selections.relation && selections.relation.trim() ? selections.relation.trim() : '朋友';
          item.innerHTML = `<span class="summary-label">关联人物</span><span class="summary-value">${actors.join('、')}（关系：${rel}）</span>`;
          summaryContainer.appendChild(item);
        }
      }

      // Initialization
      document.addEventListener('DOMContentLoaded', () => {
        // enable gender selection activation
        document.querySelectorAll('#screen-gender .card').forEach(card => {
          card.addEventListener('click', () => {
            document.getElementById('to-status').disabled = false;
          });
        });

        // map existing next/back IDs to handler
        const mapping = [
          'to-status',
          'to-profession-or-category',
          'to-profession',
          'to-features',
          'to-actor',
          'to-summary',
          'confirm-and-start'
        ];
        mapping.forEach(id => {
          const el = document.getElementById(id);
          if (el) el.addEventListener('click', () => {
            if (!el.disabled) handleNext(id);
          });
        });

        // randomize buttons
        document.querySelectorAll('.randomize-btn').forEach(btn => {
          btn.addEventListener('click', (e) => {
            handleRandomize(btn.dataset.screenId);
            e.stopPropagation();
          });
        });

        // ensure to-actor disabled until features selected
        document.getElementById('to-actor').disabled = true;
      });
    </script>
  </body>
