  document.getElementById('location').textContent = parsed['📍地点'] || '';
  document.getElementById('timestamp').textContent = parsed['🕰️时间'] || '';
  document.getElementById('inner-thoughts-content').textContent = parsed['🧠内心想法'] || '';
  document.getElementById('recent-behavior-content').textContent = parsed['📋最近性行为'] || '';

  const coreStats = ['📈好感度', '🌡️性欲值', '💧尿意值'];
  const statContainer = document.getElementById('core-stats');
  coreStats.forEach(stat => {
    if (!parsed[stat]) return;

    let val = parsed[stat].trim();
    const arrowIndex = val.indexOf('→');
    const fromRaw = val.substring(0, arrowIndex).replace(/"/g, '').trim();
    const afterArrow = val.substring(arrowIndex + 1).trim();

    let toRaw = '';
    let reason = '';
    const match = afterArrow.match(/^"?(.*?)"?\s*\((.*?)\)$/);
    if (match) {
      toRaw = match[1].trim();
      reason = match[2].trim();
    } else {
      const parts = afterArrow.split(' ');
      toRaw = parts[0].replace(/"/g, '').trim();
      reason = parts.slice(1).join(' ').trim();
    }

    const box = document.createElement('div');
    box.className = 'stat-box';
    box.innerHTML = `
      <div class="stat-label">${stat}</div>
      <div class="stat-value">
        <span class="from-value">${fromRaw}</span>
        <span class="arrow">→</span>
        <span class="to-value">${toRaw}</span>
      </div>
      <div class="stat-change-reason">${reason}</div>
    `;
    statContainer.appendChild(box);
  });

  const sections = {
    '👗服装与束具': 'apparel',
    '🩸身体细节与改造': 'body',
    '🎖️身份烙印与异常状态': 'status'
  };

  Object.entries(sections).forEach(([label, id]) => {
    const container = document.getElementById(`${id}-content`);
    const data = parsed[label];
    if (!data) return;
    const ul = document.createElement('ul');
    ul.className = 'details-list';
    Object.entries(data).forEach(([k, v]) => {
      const li = document.createElement('li');
      li.className = 'details-item';
      li.innerHTML = `<span class="details-label">${k}</span><span class="details-value">${v}</span>`;
      ul.appendChild(li);
    });
    container.appendChild(ul);
  });

  document.querySelectorAll('.drawer-button').forEach(button => {
    button.addEventListener('click', () => {
      const targetId = button.dataset.target;
      const target = document.getElementById(`${targetId}-content`);
      const isActive = button.classList.contains('active');

      document.querySelectorAll('.drawer-button').forEach(btn => btn.classList.remove('active'));
      document.querySelectorAll('.drawer-content').forEach(content => content.classList.remove('active'));

      if (!isActive) {
        button.classList.add('active');
        target.classList.add('active');
      }
    });
  });

  const toggleBtn = document.getElementById('toggle-all');
  const expandable = document.getElementById('expandable-section');
  const reasons = document.querySelectorAll('.stat-change-reason');
  let expanded = false;

  toggleBtn.addEventListener('click', () => {
    expanded = !expanded;

    if (expanded) {
      expandable.style.display = 'block';
      reasons.forEach(el => el.classList.add('active'));
      toggleBtn.textContent = '收起 ▲';
    } else {
      expandable.style.display = 'none';
      reasons.forEach(el => el.classList.remove('active'));
      toggleBtn.textContent = '展开 ▼';
    }
  });

  (function init() {
    expandable.style.display = 'none';
    reasons.forEach(el => el.classList.remove('active'));
    toggleBtn.textContent = '展开 ▼';
  })();
</script>
</body>
</html>

