  display: inline;           /* 内联显示，去掉块级间距 */
  margin: 0;
  padding: 0;
}
.option-label {
  color: #bb86fc;
  font-weight: 500;
}
.option-desc {
  color: #ccc;
}
@media (max-width: 600px) {
  .container { padding: 6px; }
  .header { font-size: 15px; margin-bottom: 4px; }
  .option { padding: 2px 3px; font-size: 11px; }
